import { Component, inject, signal } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import type { EChartsOption } from 'echarts';
import {
  TablerIconComponent, IconChevronRight, IconChevronDown, IconSettings, IconArrowsMaximize,
  IconBell, IconBuilding, IconLayoutSidebarLeftCollapse, IconLayoutSidebarLeftExpand,
  IconUsers, IconClipboardCheck, IconChecks, IconStar, IconPlus, IconRefresh,
  IconChevronRight as IconGo,
} from '@tabler/icons-angular';
import {
  HrmAppShell, HrmSideNav, HrmButton, HrmSelect, HrmOption,
  HrmStatCard, HrmChart, HrmBarList, HrmBarListItem, HrmCompetencyRadar, HrmCompetency,
  HrmKpiGauge, HrmList, HrmListItem, HrmTag,
} from 'hrm-ui';
import { DEFAULT_NAV_SECTIONS } from './_template-nav';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../doc/sg-blocks';

/** Doc page · Dashboard module (Template) — tổng quan 1 module HRM: hàng KPI (stat-card) + biểu đồ
 *  (line/donut ECharts + radar năng lực + bar-list phòng ban + gauge đúng hạn) + danh sách cần xử lý
 *  & hoạt động gần đây. Ví dụ: Tổng quan Đánh giá. Self-contained, design token, component DS. */
@Component({
  selector: 'sg-template-dashboard',
  imports: [
    NgTemplateOutlet, FormsModule, TablerIconComponent,
    HrmAppShell, HrmSideNav, HrmButton, HrmSelect, HrmStatCard, HrmChart, HrmBarList,
    HrmCompetencyRadar, HrmKpiGauge, HrmList, HrmTag,
    SgDoc, SgUse, SgDo, SgDont,
  ],
  template: `
    @if (preview) {
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screen" /></div>
    } @else {
    <sg-doc category="Template" title="Dashboard module"
      desc="Trang tổng quan 1 module HRM: hàng KPI (stat-card) + biểu đồ (xu hướng, phân bố, radar năng lực, gauge) + danh sách cần xử lý & hoạt động gần đây. Ví dụ: Tổng quan Đánh giá.">
      <div sgOverview>
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screen" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/dashboard" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="maximize" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>
      </div>
      <div sgUsage>
        <sg-use purpose="Trang đích tổng quan cho 1 module (Công/Lương/Đánh giá/Tuyển dụng): số liệu KPI, xu hướng, và việc cần xử lý — điều hướng nhanh vào chi tiết."
          [when]="when"
          behavior="Hàng KPI trên cùng (4 stat-card có delta) → khối biểu đồ (xu hướng + phân bố) → phân tích sâu (radar/bar-list/gauge) → danh sách cần xử lý & hoạt động. Bộ lọc kỳ ở header."
          avoid="Không nhồi >6 biểu đồ 1 màn; ưu tiên số liệu hành động được hơn biểu đồ trang trí." />
      </div>
      <div sgBest>
        <sg-do>KPI hàng đầu ≤4 thẻ, mỗi thẻ 1 con số + xu hướng.</sg-do>
        <sg-do>Kèm danh sách "cần xử lý" để dashboard hành động được, không chỉ để xem.</sg-do>
        <sg-dont>Đừng dùng biểu đồ 3D/trang trí — SVG/ECharts token phẳng, đọc nhanh.</sg-dont>
      </div>
    </sg-doc>
    }

    <ng-template #screen>
      <hrm-app-shell contentPad="none">
        <hrm-side-nav appSideNav [sections]="navSections" selectedKey="dashboard"
          [caretIcon]="caret" [logoSrc]="logo" [logoMarkSrc]="logoMark"
          [toggleIcon]="sbCollapse" [expandIcon]="sbExpand" [(collapsed)]="collapsedModel"
          [user]="navUser" [switchIcon]="gear" switchLabel="Cài đặt">
          <button snActions type="button" class="as-ico" aria-label="Thông báo"><tabler-icon [icon]="bell" [size]="20" /></button>
          <button snHead type="button" class="sn-acct" [class.sn-acct--mini]="collapsed()">
            <span class="sn-acct-ic"><tabler-icon [icon]="building" [size]="18" /></span>
            @if (!collapsed()) {
              <span class="sn-acct-info">
                <span class="sn-acct-name">Tập đoàn VNR</span>
                <span class="sn-acct-sub">Tài khoản doanh nghiệp</span>
              </span>
              <tabler-icon [icon]="chevDown" [size]="16" style="color:var(--text-soft)" />
            }
          </button>
        </hrm-side-nav>

        <div class="dsh-scroll">
          <div class="dsh-page">
            <header class="dsh-head">
              <div class="dsh-head-l">
                <h1 class="dsh-h1">Tổng quan Đánh giá</h1>
                <p class="dsh-hsub">Kỳ KPI Quý 3/2026 · cập nhật 10 phút trước</p>
              </div>
              <div class="dsh-head-r">
                <hrm-select [options]="periodOpts" [(ngModel)]="period" style="width:170px" />
                <hrm-button variant="default"><tabler-icon [icon]="refresh" [size]="16" /> Làm mới</hrm-button>
                <hrm-button variant="primary"><tabler-icon [icon]="plus" [size]="16" /> Tạo kỳ đánh giá</hrm-button>
              </div>
            </header>

            <!-- KPI row -->
            <div class="dsh-kpi">
              <hrm-stat-card label="Kỳ đang mở" [value]="2" [icon]="icPeriod" tone="primary" delta="+1 kỳ" deltaTone="up" />
              <hrm-stat-card label="NV đã đánh giá" [value]="248" [icon]="icUsers" tone="info" delta="+12%" deltaTone="up" />
              <hrm-stat-card label="Tỷ lệ hoàn thành" value="79%" [icon]="icDone" tone="success" delta="+6%" deltaTone="up" />
              <hrm-stat-card label="Điểm trung bình" value="4.1 / 5" [icon]="icStar" tone="warning" delta="-0.1" deltaTone="down" />
            </div>

            <!-- Charts row 1 -->
            <div class="dsh-grid dsh-grid--2a">
              <div class="dsh-card">
                <div class="dsh-card-h"><span class="dsh-card-t">Tiến độ hoàn thành theo tuần</span><hrm-tag color="green">+6%</hrm-tag></div>
                <hrm-chart [option]="lineOpt" [height]="280" />
              </div>
              <div class="dsh-card">
                <div class="dsh-card-h"><span class="dsh-card-t">Phân bố kết quả</span></div>
                <hrm-chart [option]="donutOpt" [height]="280" />
              </div>
            </div>

            <!-- Charts row 2 -->
            <div class="dsh-grid dsh-grid--3">
              <div class="dsh-card">
                <div class="dsh-card-h"><span class="dsh-card-t">Năng lực trung bình</span></div>
                <hrm-competency-radar [competencies]="competencies" [current]="radarCurrent" [required]="radarRequired"
                  [color]="pairColors" currentLabel="Hiện tại" requiredLabel="Yêu cầu" [maxScale]="5" [height]="260" />
              </div>
              <div class="dsh-card">
                <div class="dsh-card-h"><span class="dsh-card-t">Hoàn thành theo phòng ban</span></div>
                <hrm-bar-list [items]="deptBars" [format]="pct" />
              </div>
              <div class="dsh-card dsh-card--center">
                <div class="dsh-card-h"><span class="dsh-card-t">Đánh giá đúng hạn</span></div>
                <hrm-kpi-gauge [value]="86" [max]="100" label="Đúng hạn" suffix="%" [height]="230" />
              </div>
            </div>

            <!-- Lists row -->
            <div class="dsh-grid dsh-grid--2">
              <div class="dsh-card">
                <div class="dsh-card-h"><span class="dsh-card-t">Cần xử lý</span><a class="dsh-more">Xem tất cả <tabler-icon [icon]="icGo" [size]="14" /></a></div>
                <hrm-list [items]="todoItems" [bordered]="false" size="small" />
              </div>
              <div class="dsh-card">
                <div class="dsh-card-h"><span class="dsh-card-t">Hoạt động gần đây</span></div>
                <hrm-list [items]="activityItems" [bordered]="false" size="small" />
              </div>
            </div>
          </div>
        </div>
      </hrm-app-shell>
    </ng-template>
  `,
  styles: [`
    .lp-desktop { position: relative; height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-desktop--full { position: relative; height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    .lp-full { margin-top: 14px; } .lp-full-link { text-decoration: none; }
    .lp-desktop ::ng-deep .shell-content { padding: 0; }

    .as-ico { display: grid; place-items: center; width: 34px; height: 34px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .sn-acct { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg); background: var(--bg-surface); cursor: pointer; text-align: left; }
    .sn-acct--mini { width: auto; padding: 4px; border-color: transparent; background: transparent; }
    .sn-acct-ic { display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--radius-md); background: var(--primary-bg-subtle); color: var(--primary-base); flex: none; }
    .sn-acct-info { flex: 1; min-width: 0; display: flex; flex-direction: column; }
    .sn-acct-name { font-size: var(--fs-13); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .sn-acct-sub { font-size: var(--fs-12); color: var(--text-soft); }

    .dsh-scroll { height: 100%; overflow-y: auto; background: var(--bg-canvas, var(--bg-surface-subtle)); }
    .dsh-page { max-width: 1240px; margin: 0 auto; padding: var(--space-6, 24px) var(--space-6, 24px) var(--space-10, 40px); display: flex; flex-direction: column; gap: var(--space-4, 16px); }

    .dsh-head { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-4, 16px); flex-wrap: wrap; }
    .dsh-h1 { margin: 0; font-size: var(--fs-24, 24px); font-weight: var(--font-bold, 700); color: var(--text-strong); letter-spacing: -.01em; }
    .dsh-hsub { margin: var(--space-1, 4px) 0 0; font-size: var(--fs-13, 13px); color: var(--text-sub); }
    .dsh-head-r { display: flex; align-items: center; gap: var(--space-2, 8px); flex-wrap: wrap; }

    .dsh-kpi { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-3, 12px); }
    @media (max-width: 900px) { .dsh-kpi { grid-template-columns: repeat(2, 1fr); } }

    .dsh-grid { display: grid; gap: var(--space-3, 12px); }
    .dsh-grid--2 { grid-template-columns: 1fr 1fr; }
    .dsh-grid--2a { grid-template-columns: 1.6fr 1fr; }
    .dsh-grid--3 { grid-template-columns: 1.1fr 1fr 0.9fr; }
    @media (max-width: 980px) { .dsh-grid--2, .dsh-grid--2a, .dsh-grid--3 { grid-template-columns: 1fr; } }

    .dsh-card { background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl); padding: var(--space-4, 16px); min-width: 0; }
    .dsh-card--center { display: flex; flex-direction: column; }
    .dsh-card-h { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2, 8px); margin-bottom: var(--space-2, 8px); }
    .dsh-card-t { font-size: var(--fs-14, 14px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    :host ::ng-deep .ant-tag { margin: 0; }
    .dsh-more { display: inline-flex; align-items: center; gap: 2px; font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500); color: var(--primary-base); cursor: pointer; text-decoration: none; }
    .dsh-more:hover { text-decoration: underline; }
  `],
})
export class SgTemplateDashboard {
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;

  protected readonly caret = IconChevronRight;
  protected readonly maximize = IconArrowsMaximize;
  protected readonly chevDown = IconChevronDown;
  protected readonly bell = IconBell;
  protected readonly building = IconBuilding;
  protected readonly sbCollapse = IconLayoutSidebarLeftCollapse;
  protected readonly sbExpand = IconLayoutSidebarLeftExpand;
  protected readonly plus = IconPlus;
  protected readonly refresh = IconRefresh;
  protected readonly icGo = IconGo;
  protected readonly icPeriod = IconClipboardCheck;
  protected readonly icUsers = IconUsers;
  protected readonly icDone = IconChecks;
  protected readonly icStar = IconStar;
  protected readonly logo = '/assets/vnr-logo-full.svg';
  protected readonly logoMark = '/assets/vnr-logo-mark.svg';
  protected readonly collapsed = signal(false);
  protected get collapsedModel(): boolean { return this.collapsed(); }
  protected set collapsedModel(v: boolean) { this.collapsed.set(v); }
  protected readonly navUser = { name: 'Đặng Anh', email: 'danganh@vnr.vn' };
  protected readonly gear = IconSettings;
  protected readonly when = ['Trang đích 1 module (Tổng quan)', 'Theo dõi KPI + việc cần xử lý', 'Điều hướng nhanh vào chi tiết'];

  protected readonly navSections = DEFAULT_NAV_SECTIONS;

  private _p = signal('q3');
  protected get period() { return this._p(); }
  protected set period(v: string) { this._p.set(v); }
  protected readonly periodOpts: HrmOption[] = [
    { value: 'q3', label: 'Quý 3 / 2026' }, { value: 'q2', label: 'Quý 2 / 2026' },
    { value: 'q1', label: 'Quý 1 / 2026' }, { value: 'year', label: 'Cả năm 2026' },
  ];

  // ── ECharts options ──
  /** Palette biểu đồ PASTEL (mềm, tươi, đồng bộ với donut "Phân bố kết quả"; hợp Light/Dark) —
   *  override palette theme mặc định (--data-*) vốn chìm ở nền tối. Màu dữ liệu chart = ngoại lệ token. */
  private readonly viz = ['#A78BFA', '#38BDF8', '#34D399', '#FBBF24', '#FB7185', '#60A5FA', '#FB923C', '#2DD4BF'];
  /** 2 màu pastel cho line + radar (hiện tại · mục tiêu/yêu cầu). */
  protected readonly pairColors = ['#A78BFA', '#38BDF8'];
  private readonly weeks = ['T1', 'T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'T8'];
  protected readonly lineOpt: EChartsOption = {
    color: ['#A78BFA', '#38BDF8'],
    tooltip: { trigger: 'axis' },
    legend: { data: ['Đã đánh giá', 'Mục tiêu'], bottom: 0 },
    grid: { left: 8, right: 12, top: 16, bottom: 34, containLabel: true },
    xAxis: { type: 'category', boundaryGap: false, data: this.weeks },
    yAxis: { type: 'value' },
    series: [
      { name: 'Đã đánh giá', type: 'line', smooth: true, areaStyle: { opacity: 0.22 }, data: [28, 62, 96, 128, 165, 198, 226, 248] },
      { name: 'Mục tiêu', type: 'line', smooth: true, lineStyle: { type: 'dashed' }, data: [39, 78, 117, 156, 195, 234, 273, 312] },
    ],
  };
  protected readonly donutOpt: EChartsOption = {
    color: ['#34D399', '#38BDF8', '#FBBF24', '#FB7185'],
    tooltip: { trigger: 'item' },
    legend: { bottom: 0 },
    series: [{
      name: 'Kết quả', type: 'pie', radius: ['48%', '70%'], center: ['50%', '44%'],
      label: { show: false }, data: [
        { value: 64, name: 'Xuất sắc' }, { value: 148, name: 'Đạt' },
        { value: 28, name: 'Cần cải thiện' }, { value: 8, name: 'Không đạt' },
      ],
    }],
  };

  // ── Radar ──
  protected readonly competencies: HrmCompetency[] = [
    { name: 'Chuyên môn' }, { name: 'Giao tiếp' }, { name: 'Lãnh đạo' },
    { name: 'Teamwork' }, { name: 'Sáng tạo' }, { name: 'Kỷ luật' },
  ];
  protected readonly radarCurrent = [4.2, 3.8, 3.4, 4.4, 3.9, 4.6];
  protected readonly radarRequired = [4, 4, 4, 4, 4, 4];

  // ── Bar list (dept completion) ──
  protected readonly deptBars: HrmBarListItem[] = [
    { label: 'Kỹ thuật', value: 92, color: this.viz[0] }, { label: 'Kinh doanh', value: 81, color: this.viz[1] },
    { label: 'Nhân sự', value: 88, color: this.viz[2] }, { label: 'Kế toán', value: 74, color: this.viz[3] },
    { label: 'Marketing', value: 67, color: this.viz[4] },
  ];
  protected readonly pct = (v: number): string => `${v}%`;

  // ── Lists ──
  protected readonly todoItems: HrmListItem[] = [
    { title: 'Duyệt kết quả — Phòng Kinh doanh', description: '12 phiếu chờ duyệt', avatar: 'KD', extra: 'Chờ duyệt' },
    { title: 'Nhắc hoàn thành tự đánh giá', description: '64 NV chưa nộp', avatar: 'TĐ', extra: 'Quá hạn 2 ngày' },
    { title: 'Hiệu chỉnh điểm — Phòng Kỹ thuật', description: '3 trường hợp lệch chuẩn', avatar: 'KT', extra: 'Cần xem' },
    { title: 'Chốt kỳ KPI Quý 3', description: 'Còn 5 ngày đến hạn', avatar: 'Q3', extra: 'Sắp hạn' },
  ];
  protected readonly activityItems: HrmListItem[] = [
    { title: 'Nguyễn Thị Mai Anh', description: 'Hoàn thành tự đánh giá', avatar: 'NA', extra: '2 giờ trước' },
    { title: 'Trần Văn Hùng', description: 'Duyệt 8 phiếu đánh giá', avatar: 'TH', extra: '3 giờ trước' },
    { title: 'Lê Quốc Bảo', description: 'Yêu cầu hiệu chỉnh điểm', avatar: 'LB', extra: 'Hôm qua' },
    { title: 'Phạm Hồng Nhung', description: 'Nộp đánh giá 360°', avatar: 'PN', extra: 'Hôm qua' },
  ];
}
